{
  "title": "The Mirror Rescue of the Broken City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara plots a course into the ruined city.",
      "visual_description": "A windswept ridge at dusk overlooking a shattered royal skyline; an ink-stained coat flaps as a brass compass spins over a hand-drawn map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of the road ahead.",
      "visual_description": "A small camp under a leaning road sign; the lamp's single flame-eye blazes, casting long warning shadows across Mara's map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox sniffs the broken gate.",
      "visual_description": "A clockwork fox with blue glass eyes peers through the bent bars of an enormous castle gate, key-wind tail ticking softly.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet steps out of a broken pane as if from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They find the sleeping tax collector blocking the way.",
      "visual_description": "A plump official snores at a toll booth, ledger book under his cheek, stamped papers fluttering from his sleeves in the wind.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The lamp whispers a route past the cursed tower.",
      "visual_description": "A spiraling black tower looms; the oracle lamp glows green near a cracked alley, beckoning the team away from the obvious path.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox scouts an armored patrol.",
      "visual_description": "From behind a fallen royal banner, the clockwork fox watches metal-booted shapes march down a rubble-strewn boulevard.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver slips through a shop window.",
      "visual_description": "The diver dives headfirst into a tall pane of glass, body rippling like water as the helmet glints with reflected torchlight.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara decodes a torn royal banner.",
      "visual_description": "Beneath a half-burned banner, Mara traces faded heraldry with inky fingers while the tin fox shines lamplight on the cloth.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp names the magic door.",
      "visual_description": "A great brass door etched with runes pulses faintly; the lamp's eye reflects in every glyph as Mara raises her compass.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver pulls the captive from a mirror.",
      "visual_description": "Inside a candle-lit chamber, the diver hauls the sleeping tax collector from a tall standing mirror, water-light dripping off both of them.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The tax collector refuses to wake up.",
      "visual_description": "Slumped against a column, the official snores while stamped forms drift around him; Mara tugs his sleeve in exasperation.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox sets off a distant alarm bell.",
      "visual_description": "The clockwork fox yanks a frayed rope on a rooftop, sending a cracked bell swinging above the smoldering rooftops as a diversion.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The lamp warns of a collapsing arch.",
      "visual_description": "Stones grind overhead in a colonnade; the lamp's flame-eye flares red as the diver shields the snoring official with a reflective coat.",
      "characters": ["oracle_lamp", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Mara redraws the map on the run.",
      "visual_description": "Sprinting through a flooded plaza, Mara sketches frantically on damp parchment while the tin fox bounds ahead through puddled reflections.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Glass Diver opens a window across the river.",
      "visual_description": "At the foot of a ruined keep, the diver presses both palms to a glowing pane that ripples like a vertical pond, revealing a far bridge.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The team races onto the long bridge.",
      "visual_description": "A narrow stone bridge stretches over a chasm of mist; Mara, the tin fox, and the diver carry the sleeping official as the lamp lights the way.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They look back at the broken city, free.",
      "visual_description": "On the far cliff at dawn, the rescuers stand silhouetted against pale sky; the tax collector finally blinks awake as the lamp's eye dims to a gentle glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

